class Solution:
    def countOfArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7
        e, o = m // 2, m - m // 2
        dp = [[[0] * 2 for _ in range(k + 1)] for _ in range(n)]
        dp[0][0][0], dp[0][0][1] = o, e
        for i in range(1, n):
            for j in range(k + 1):
                dp[i][j][0] = (dp[i-1][j][0] + dp[i-1][j][1]) * o % MOD
                v = dp[i-1][j][0] * e
                if j > 0:
                    v += dp[i-1][j-1][1] * e
                dp[i][j][1] = v % MOD
        return (dp[n-1][k][0] + dp[n-1][k][1]) % MOD

